package cn.balltv.portal;
import org.junit.*;import static org.junit.Assert.*;import java.util.*;import org.json.*;
public class TeamNamesTest {
 Feeds.Match m(String home,String away,String time){Feeds.Match m=new Feeds.Match();m.source=home;m.id=home;m.home=home;m.away=away;m.sport="2";m.time=time;m.title=home+" vs "+away;return m;}
 @Test public void screenshotPhilippineFixtureMergesTranslationsAndAbbreviations(){List<Feeds.Match> rows=Arrays.asList(m("CSJL Knight","UPHSD Altas","2026-11-10 15:00"),m("CSJL骑士","UPHSD阿特拉斯","2026-11-10 15:00"),m("莱特兰骑士","永久阿尔塔斯","2026-11-10 15:00"));ArrayList<Events.Group> grouped=Events.group(rows,false);assertEquals(1,grouped.size());assertEquals(3,grouped.get(0).sourceCount());}
 @Test public void screenshotAsianTournamentFixtureMergesChineseAndEnglish(){assertEquals(1,Events.group(Arrays.asList(m("Hanoi Da Mau Bulls","Macau Black Knights","2026-11-10 15:00"),m("河内多毛公牛","澳门黑骑士","2026-11-10 15:00")),false).size());}
 @Test public void sameTimeAndSameScoreDoNotMergeDifferentNamedFixtures(){Feeds.Match a=m("甲","乙","2026-11-10 15:00"),b=m("丙","丁","2026-11-10 15:00");a.score=b.score="39 : 33";assertEquals(2,Events.group(Arrays.asList(a,b),false).size());}
 @Test public void womenAndMenOrDistinctMacauTeamsDoNotMerge(){assertNotEquals(Events.canonical("CSJL Knight"),Events.canonical("CSJL Knight Women"));assertNotEquals(Events.canonical("Macau Black Knights"),Events.canonical("澳门黑熊"));}
 @Test public void coPublishedHomeAndAwayTranslationsLearnWithoutCrossPairing()throws Exception{TeamNames.learn(new JSONObject("{home_name_zh:'测试大学甲',home_name_en:'Test University Alpha',away_name_zh:'测试大学乙',away_name_en:'Test University Beta'}"));assertEquals(Events.canonical("测试大学甲"),Events.canonical("Test University Alpha"));assertEquals(Events.canonical("测试大学乙"),Events.canonical("Test University Beta"));assertNotEquals(Events.canonical("Test University Alpha"),Events.canonical("Test University Beta"));}
 @Test public void nestedTeamObjectLearnsAuthoritativeNamesOnly()throws Exception{TeamNames.learn(new JSONObject("{home:{name_zh:'测试学院丙',name_en:'Test College Gamma'},league:{name_zh:'测试联赛',name_en:'Test League'}}"));assertEquals(Events.canonical("测试学院丙"),Events.canonical("Test College Gamma"));assertNotEquals(Events.canonical("测试联赛"),Events.canonical("Test League"));}
 @Test public void rematchAtDistantTimeRemainsSeparate(){assertEquals(2,Events.group(Arrays.asList(m("CSJL Knight","UPHSD Altas","2026-11-10 15:00"),m("CSJL骑士","UPHSD阿特拉斯","2026-11-10 20:00")),false).size());}

 @Test public void finishedTranslationDoesNotRemainUnfinishedThroughAnotherSource(){Feeds.Match english=m("CSJL Knight","UPHSD Altas","2026-11-10 15:00"),chinese=m("CSJL骑士","UPHSD阿特拉斯","2026-11-10 15:00");english.eventState="finished";chinese.status="live";Events.Group group=Events.group(Arrays.asList(english,chinese),false).get(0);assertTrue(LiveState.finished(group,Events.epoch("2026-11-10 17:00")));}
 @Test public void nested74SourceMetadataTeachesAliasesBeforeDiscardingRawFields()throws Exception{JSONObject o=new JSONObject("{items:[{id:600,home_team:{name:'测试队四',name_en:'Test Team Four'},away_team:{name:'测试队五',name_en:'Test Team Five'},category:{key:'basketball'},start_time:'2026-11-10 15:00',status:'live'}]}");MoreSources.parse74(o,"schedule");assertEquals(Events.canonical("测试队四"),Events.canonical("Test Team Four"));assertEquals(Events.canonical("测试队五"),Events.canonical("Test Team Five"));}
}
